// TypeScript port of the booleans group's translator: docs/spikes/solidcraft-referee/contract/bool-translate-r3.mjs (GENERATED by make-bool-translate-r3.mjs from phase0/translate.mjs plus asserted
// patches; the file booleans.json was built with) with booleans.guard.mjs, booleans.slow.mjs (booleans-guard.ts, booleans-slow.ts) and the piece-collecting executor
// booleans-r3/combine-exec.mjs (execCombine below). Behaviour-preserving: same guards in the same order, same sentences, same command lists, same engine calls.
//
// THE ORIGINAL IS NOT A COPY OF THE PHASE 4 TRANSLATOR. It is phase0/translate.mjs with a handful of patches and its own SYNCHRONOUS loop. The layer's base is the phase 4 translator
// (translate.ts). The 'booleans' set is therefore
//     base (phase 4) planners for every kind except combine  +  the group's guarded combine planner and executor  +  the group's own loop,
// and it equals the original on a document only where phase0 and phase 4 plan every OTHER feature the same way. NOTES.md ("Fold 5") lists, kind by kind, where they do not
// (a shell, a fillet, a draft: the original asks brep-rs for the point of a name, the port reads the engine's topology; a constrained sketch used by a pull, pocket, spin, groove or loft).
//
// WHAT THE GROUP ADDS TO A COMBINE (join / cut / keep):
//   * the pure guard (G1..G18, G20: booleans-guard.ts) decides BEFORE the engine is called, from the bounding boxes of the operands and their lineage (booleans-slow.ts);
//   * the executor collects every piece a cut or a keep leaves (a handle can be several pieces), runs keep(a, b, c, ...) as one intersect per tool operand, and keeps a tool alive (keep_tools)
//     when a LATER feature still uses it (G8);
//   * the after-the-build check (afterCombine: G4b a cut that removed nothing, G19 the result sticks out of the boxes of the operands, G21 a cut that leaves a curved sliver) can still refuse a
//     build the engine accepted;
//   * every raw message becomes one student sentence (plainSentence, G9); a handle that is several pieces used by a step that needs one piece gets its own sentence (G12);
//   * TIME. The group's rule for the page (booleans.guard.mjs, header) is: every engine run for a combine has BUDGET_S (45) seconds. The original translator has no code for it (its harness kills
//     the whole case after 60 s). The layer asks the host: ctx.runSC(cmds, { budgetS }) with budgetS = 45 + 1.5 x the CPU the last run used (the same rule as the holes group's G-BUDGET); a reply
//     { ok: false, timedOut: true } refuses the combine with SENTENCES.budget ("took longer than 45 seconds ... nothing was changed"), guard G-BUDGET. THIS IS ADVICE: a host whose runSC ignores
//     the option leaves the run unbounded, and nothing in this package can stop it.
//
// IN THE UNIFIED SET (unified.ts) this step owns every combine, and ALSO applies the extrude-pocket group's join checks to it (they are safety checks of that group that look at a kind this
// group owns there; without them a join that the extrude-pocket set refuses would be built): before the build, a slanted round pull that runs into another part and two plain blocks that only touch
// (extrude-pocket.ts joinPreflight); after it, the contact and flush-step checks (verifyUnion; no further engine run), and, only when ctx.unifiedEpJoinChecks is 'full', its inclusion-exclusion
// consistency check (V(join) against the sum of its parts, measured in scratch sessions: further engine runs on every join). They run only when st.unified is set and ctx.unifiedEpJoinChecks is not
// 'off'; the 'booleans' set alone never runs them. Their sentences are the extrude-pocket group's own, and guard 'EP-JOIN' names them. WHY 'cheap' IS THE DEFAULT: see NOTES.md, Fold 5 / Unified.
//
// The group is NOT accepted in Phase 1 (LAYER-CONTRACT.md, "booleans: unresolved"). The known holes are in this port on purpose: see NOTES.md, Fold 5.
//
// No kernel is named: everything that touches an engine comes in through the context object (ctx.runSC, ctx.topologyOf, ctx.arc, ctx.mt).
// Non-null assertions (!) stand for fields the feature's kind guarantees on a well-formed doc; the original reads them unguarded, so a malformed doc throws the same TypeError, which the step
// turns into the same translator-error refusal (and, for a combine, into the same plain sentence).
import type { Feature } from '@shuff57/reshape-script/model-types';
import type { Cmd, RunResult, TranslateCtx } from './types.js';
import { BASE_PROFILE, aggregate, frameWithMt, isVerbatimGuard, planFeature, refuse, resolveNamesFor } from './translate.js';
import type { Aggregate, FeatureResult, LoopEnv, Plan, PlanCtx, Planner, Profile, TranslateState } from './translate.js';
import { joinPreflight, verifyUnion } from './extrude-pocket.js';
import { sampleOutline } from './outline-guard.js';
import type { GuardOutline } from './outline-guard.js';
import { orient } from './booleans-slow.js';
import { SKETCH_VOLUME_GUARD, sketchVolumeRefusal } from './sketch-volume.js';
import { POCKET_CUT_GUARD, pocketCutRefusal, rememberRun } from './pocket-cut.js';
import { hollowRefusal } from './hollow-check.js';
import { motionRefusal, motionRepair } from './move-turn.js';
import { beforeOf, blendOf, blendRefusal } from './fillet-chain.js';
import type { SketchRead, SlowFeat } from './booleans-slow.js';
import { BUDGET_S, SENTENCES, afterCombine, describe, guardCombine, plainPieces, plainSentence, reusedTools } from './booleans-guard.js';
import type { CombineView, GuardHit } from './booleans-guard.js';
import { ERRORED_BODY_GUARD, erroredBodySentence } from './errored-body.js';

export {
  BUDGET_S as BOOLEANS_BUDGET_S, SENTENCES as BOOLEANS_SENTENCES, SLIVER as BOOLEANS_SLIVER, afterCombine, guardCombine, plainPieces, plainSentence, reusedTools, lintSentence as booleansLintSentence, explainCombineArgs, explainFront, describe as describeOperand, obbDepth,
} from './booleans-guard.js';
export type { Desc, GuardOp, GuardHit, CombineView } from './booleans-guard.js';
export * as booleansSlow from './booleans-slow.js';

/** The kind this set owns. */
export const BOOL_KINDS = ['combine'];
/** The guards of this set that look at runs of kinds it does not own: none. Its time limit applies to the runs of a combine only (the original has no time limit at all). */
export const BOOL_CROSS_KIND_GUARDS: string[] = [];

/** The fields of a feature this module reads. */
interface BF extends SlowFeat {
  id: string;
  kind: string;
  op?: string;
  targets?: string[];
  target?: string;
  into?: string;
  shape?: string;
  points?: number[][];
  bulges?: Record<number, number>;
}
const BFV = (f: Feature): BF => f as unknown as BF;

// ---- state -----------------------------------------------------------------------------------------------------------------------------
/** The group's bookkeeping beside the generic state. */
export interface BoolState {
  /** every feature of the document by id (the original's ctx.featById) */
  featById: Record<string, Feature>;
  /** the features that change an earlier id in place (a hole, pocket, groove, shell, fillet, draft), by the id they change */
  affects: Record<string, string[]>;
  /** the whole document's features (the original's reusedTools reads doc.features: a tool a LATER feature uses again is kept alive) */
  docFeatures: Feature[];
  /** the names of every body the engine held after the last accepted feature (the original's st.lastNames) */
  lastNames: string[] | undefined;
  /** CPU seconds the last run used, when the host reports it: the budget of the next run is BUDGET_S + 1.5 x this */
  lastRunS: number;
}
export function initBool(st: TranslateState, doc?: { features: Feature[] }): void {
  const feats = doc?.features ?? [];
  const featById: Record<string, Feature> = Object.fromEntries(feats.map((g) => [g.id, g]));
  const affects: Record<string, string[]> = {};
  for (const g of feats) {
    if (['hole', 'pocket', 'groove', 'shell', 'fillet', 'draft'].includes(g.kind)) {
      const v = BFV(g);
      const t = g.kind === 'pocket' || g.kind === 'groove' ? v.into : v.target;
      if (t) (affects[t] ??= []).push(g.id);
    }
  }
  st.bool = { featById, affects, docFeatures: feats, lastNames: undefined, lastRunS: 0 };
}

// ---- reading a sketch for the guards (the host side of the original, run-booleans.mjs) ---------------------------------------------------------
/** The slice of revolve-groove.guard.mjs profileInfo the booleans runner reads (a ring-shaped spin is a TUBE tool, G10). The revolve-groove group is not folded yet: when it is, this should import its profileInfo. */
const AXIS_TOL = 1e-9;
const SAME = 1e-9;
interface ProfileRead { ok: boolean; scale: number; umin: number; umax: number }
function profileInfo(sk: Feature, arc: TranslateCtx['arc']): ProfileRead {
  const skv = sk as unknown as { shape?: string; points?: number[][] };
  const o = arc.outlineOf(sk as never);
  if (!o.ok) return { ok: false, scale: 0, umin: 0, umax: 0 };
  if (skv.shape === 'circle') {
    const [a, b] = o.points;
    const c = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
    const r = Math.hypot(b[0] - a[0], b[1] - a[1]) / 2;
    return { ok: true, scale: Math.max(1e-12, Math.abs(c[0]) + r, Math.abs(c[1]) + r), umin: c[0] - r, umax: c[0] + r };
  }
  const { pts } = sampleOutline(o as GuardOutline, arc);
  const us = pts.map((p) => p[0]);
  const scale = Math.max(1e-12, ...pts.flat().map(Math.abs));
  // the original also computes the signed area, duplicate corners and collinearity here; none of it is read by the booleans runner
  void SAME;
  return { ok: true, scale, umin: Math.min(...us), umax: Math.max(...us) };
}
/** a revolve whose profile stays off its axis is a RING (tube) tool: the descriptor carries {angle} */
function ringOf(feat: BF | null | undefined, st: TranslateState, ctx: Pick<TranslateCtx, 'arc'>): { angle?: number } | null {
  if (feat?.kind !== 'revolve') return null;
  const sk = st.bool!.featById[feat.target!];
  if (!sk) return null;
  const p = profileInfo(sk, ctx.arc);
  if (!p.ok) return null;
  const tol = AXIS_TOL * Math.max(1, p.scale);
  return (p.umin > tol || p.umax < -tol) ? { angle: feat.angle } : null;
}
/** the world frame of a sketch and the directions of its straight edges, for the slant predictor (booleans-slow) */
function sketchInfoOf(st: TranslateState, ctx: Pick<TranslateCtx, 'arc' | 'mt'>): (skId: string) => SketchRead | null {
  return (skId) => {
    const sk = st.bool!.featById[skId] as unknown as (BF & { kind: string }) | undefined;
    if (!sk || sk.kind !== 'sketch') return null;
    try {
      const fr = frameWithMt(sk as never, ctx.mt); const o = ctx.arc.outlineOf(sk as never);
      if (sk.shape === 'circle') return { n: fr.n, edgeNormals: [], arcs: true };
      const pts = o.points ?? sk.points; const bul = o.bulges ?? sk.bulges ?? {};
      const edgeNormals: number[][] = []; let arcs = false;
      for (let i = 0; i < pts!.length; i++) {
        const j = (i + 1) % pts!.length; const dx = pts![j][0] - pts![i][0]; const dy = pts![j][1] - pts![i][1]; const L = Math.hypot(dx, dy); if (L < 1e-12) continue;
        if (Math.abs(bul[i] ?? 0) > 1e-12) { arcs = true; continue; }
        const nx = dy / L; const ny = -dx / L; // in-plane normal of the edge
        edgeNormals.push([0, 1, 2].map((k) => fr.u[k] * nx + fr.v[k] * ny));
      }
      return { n: fr.n, edgeNormals, arcs, axis: fr.v };
    } catch { return null; }
  };
}

// ---- the combine planner (the patched case 'combine' of the original) ------------------------------------------------------------------------
/** A refusal with the code of the guard that made it. */
interface BoolRefusal { refusal: string; guard?: string; final?: true }
/** The plan of a combine: the operands' body names, which tools a later feature uses again, and what the after-the-build check needs. (The original's plan.r3.) */
interface BoolPlan {
  r3: { op: string; groups: string[][]; keep: boolean[] };
  produces: string[];
  before: Aggregate | undefined;
  boxes: Array<number[] | undefined>;
  consumes: string[];
}
/** The unified set applies the extrude-pocket group's join checks to every combine (see the header); the flag lets a test measure what that costs. */
const epJoinLevel = (st: TranslateState, ctx: Pick<TranslateCtx, 'unifiedEpJoinChecks'>): 'off' | 'cheap' | 'full' => (st.unified ? (ctx.unifiedEpJoinChecks ?? 'cheap') : 'off');
const boolCombine: Planner = (fe, st, ctx, h) => {
  const f = BFV(fe);
  const ds = f.targets!.map((t) => h.dep(t)).find(Boolean);
  if (ds) return refuse(ds);
  if (f.targets!.length < 2) return refuse(`${f.id} (combine): needs two or more targets`);
  const all = f.targets!.map((t) => h.needBody(t));
  if (all.some((b) => !b || !b.length)) return refuse(`${f.id} (combine): a target has no body`); // BOOLEANS-R3: several pieces are fine now
  const parts = all as string[][];
  // BOOLEANS-GUARD (G1..G7, G10..): refuse BEFORE any engine call, in a student sentence
  const ops = f.targets!.map((t) => ({ id: t, measure: st.measure[h.headOf(t)] ?? st.measure[t], feat: st.head[t] ? null : BFV(st.bool!.featById[t]), pieces: (st.bodies[h.headOf(t)] ?? []).length }));
  if (ops.every((o) => o.measure)) {
    const sketchInfo = sketchInfoOf(st, ctx);
    const g = guardCombine(f as unknown as CombineView, ops.map((o) => ({ id: o.id, d: describe(o.measure, o.feat, { ring: ringOf(o.feat, st, ctx), pieces: o.pieces, info: orient(o.id, st.bool!.featById as unknown as Record<string, SlowFeat>, sketchInfo, st.bool!.affects) }) })));
    if (g) return { refusal: g.sentence, guard: g.code } as BoolRefusal;
  }
  // the extrude-pocket group's join checks that are decided before the engine is called (unified set only; its own sentence, not mapped by plainSentence)
  if (epJoinLevel(st, ctx) !== 'off' && f.op === 'union') {
    const bad = joinPreflight(fe, parts.flat(), st);
    if (bad) return { refusal: bad, guard: 'EP-JOIN', final: true } as BoolRefusal;
  }
  // BOOLEANS-GUARD (G8): a tool that a LATER feature uses again survives (keep_tools)
  const keepIds = reusedTools(f as unknown as CombineView, st.bool!.docFeatures as never);
  const plan: BoolPlan = {
    r3: { op: f.op!, groups: parts, keep: f.targets!.map((t, i) => i > 0 && keepIds.includes(t)) },
    produces: parts[0], before: st.measure[h.headOf(f.targets![0])] ?? st.measure[f.targets![0]], boxes: f.targets!.map((t) => (st.measure[h.headOf(t)] ?? st.measure[t])?.bbox),
    consumes: f.targets!.filter((t, i) => i === 0 || !keepIds.includes(t)),
  };
  return plan as unknown as Plan;
};

// ---- the executor (booleans-r3/combine-exec.mjs) --------------------------------------------------------------------------------------------------
type RunFn = (cmds: Cmd[]) => RunResult | Promise<RunResult>;
interface ExecOk { cmds: Cmd[]; produces: string[]; res: RunResult }
interface ExecErr { err: string; timedOut?: boolean; /** the run's reply carried an errored body (errored-body.ts) */ errored?: true }
/**
 * The ONE function the combine step needs to be right for results that fall into several pieces and for keep() of three or more shapes. The caller hands it `runSC(commands) -> engine reply`.
 * Facts it rests on (probe-pieces.mjs, raw SolidCraft, no translator):
 *   1. when a cut / intersect leaves SEVERAL separate solids, solidcraft keeps the first under the target's name and names the others "<name> (1)", "<name> (2)", ... so the new pieces are found by DIFFING the body list.
 *   2. an n-ary solid.combine intersect is target & (union of the tools), NOT the intersection of all of them, so keep(a, b, c) is one intersect per tool operand, in order.
 *   3. a cut or an intersect of a piece that the tool does not touch is ok:true, so a handle that is several pieces is combined PIECE BY PIECE, the tool kept alive (keep_tools) until the last piece.
 *   4. a tool that is several pieces is fine as it stands: cut = minus the union, intersect = with the union.
 * Returns {cmds, produces, res} or {err}. `produces` is every piece of the result (the handle of the combine feature); an empty list is reported as the same "no body named ..." text the pristine translator used.
 */
export async function execCombine(r3: BoolPlan['r3'], accepted: Cmd[], runSC: RunFn, live0: string[]): Promise<ExecOk | ExecErr> {
  const { op, groups, keep } = r3; // groups[i] = body names of operand i (several when an earlier combine left pieces); keep[i] = operand i must survive this combine
  const cmds: Cmd[] = []; let live = new Set(live0); let res: RunResult | null = null;
  const run = async (cmd: Cmd): Promise<{ names: Set<string> } | ExecErr> => {
    let r: RunResult; try { r = await runSC([...accepted, ...cmds, cmd]); } catch (e) { r = { ok: false, failed: { error: `WASM TRAP: ${(e as Error).message}` } }; }
    if (r.timedOut) return { err: r.failed ? `${r.failed.command}: ${r.failed.error}` : 'TIME BUDGET: the run did not finish', timedOut: true };
    if (!r.ok) return { err: r.failed ? `${r.failed.command}: ${r.failed.error}` : String(r.error ?? 'unknown'), ...(r.erroredBody ? { errored: true as const } : {}) };
    cmds.push(cmd); res = r;
    return { names: new Set(r.measure!.bodies.map((b) => b.name)) };
  };
  // one solid.combine of `piece` with `tools`; returns the pieces that came out of it (the piece itself if it survived, plus every NEW body name)
  const step = async (piece: string, tools: string[], keepTools: boolean): Promise<{ pieces: string[] } | ExecErr> => {
    const before = live;
    const r = await run({ command: 'solid.combine', params: { target: piece, tools, operation: op === 'union' ? 'join' : op === 'subtract' ? 'cut' : 'intersect', ...(keepTools ? { keep_tools: true } : {}) } });
    if ('err' in r) return r;
    live = r.names;
    const out: string[] = [];
    if (r.names.has(piece)) out.push(piece);
    for (const n of r.names) if (!before.has(n)) out.push(n);
    return { pieces: out };
  };
  const toolGroups = groups.slice(1);
  let pieces = groups[0].slice();
  if (op === 'union') {
    // join: everything is fused into the first piece; a kept operand is fused one operand at a time so keep_tools can be set on it
    const anyKeep = keep.some(Boolean);
    const extra = pieces.slice(1); // the other pieces of the first operand are fused in as tools too
    if (!anyKeep) {
      const r = await step(pieces[0], [...extra, ...toolGroups.flat()], false);
      if ('err' in r) return r;
      pieces = r.pieces;
    } else {
      let cur = pieces[0];
      if (extra.length) { const r = await step(cur, extra, false); if ('err' in r) return r; cur = r.pieces[0] ?? cur; }
      for (let j = 0; j < toolGroups.length; j++) { const r = await step(cur, toolGroups[j], !!keep[j + 1]); if ('err' in r) return r; cur = r.pieces[0] ?? cur; }
      pieces = [cur];
    }
  } else {
    // cut: when no operand is kept, all tools go into ONE combine per piece (the shape the round-2 measurements used); intersect (and a cut with a kept tool) goes one tool operand at a time
    const oneShot = op === 'subtract' && !keep.some(Boolean);
    const rounds = oneShot ? [{ tools: toolGroups.flat(), keepTools: false }] : toolGroups.map((g, j) => ({ tools: g, keepTools: !!keep[j + 1] }));
    for (const rd of rounds) {
      const next: string[] = [];
      for (let i = 0; i < pieces.length; i++) {
        const r = await step(pieces[i], rd.tools, rd.keepTools || i < pieces.length - 1);
        if ('err' in r) return r;
        next.push(...r.pieces);
      }
      pieces = next;
      if (!pieces.length) break;
    }
  }
  if (!pieces.length) return { err: `solidcraft ran the commands but no body named ${groups[0].join(', ')} came back` };
  return { cmds, produces: pieces, res: res! };
}

// ---- the loop ------------------------------------------------------------------------------------------------------------------------------------
/** What the step plans with: the base planners, and this group's combine. The dependency, outline and planner-error wording is the base's. */
const BOOL_PLAN: Profile = { ...BASE_PROFILE, name: 'booleans(plan)', planners: { combine: boolCombine } };

interface StepPlan { variants?: Cmd[][]; produces: string[]; consumes: string[]; pickedFrom?: string; evidence?: FeatureResult['evidence']; r3?: BoolPlan['r3']; before?: Aggregate; boxes?: Array<number[] | undefined>; __res?: RunResult }

export async function boolStep(f: Feature, idx: number, env: LoopEnv): Promise<void> {
  const { doc, ctx, st, accepted, out } = env;
  const bs = st.bool!;
  const prefix = doc.features.slice(0, idx);
  const note = (o: Omit<FeatureResult, 'id' | 'kind'>): void => { out.push({ id: f.id, kind: f.kind, ...o }); };
  if (f.kind === 'sketch') st.sketches[f.id] = f;
  const resolved = await resolveNamesFor(f, prefix, env);
  const fctx: PlanCtx = { ...ctx, resolve: (name) => resolved.get(name) ?? null };
  let planned: Plan;
  let guard: string | undefined;
  try { planned = planFeature(f, st, fctx, BOOL_PLAN); } catch (e) { planned = refuse(`${f.id} (${f.kind}): translator error: ${(e as Error).message}`); }
  if ('refusal' in planned) {
    guard = (planned as BoolRefusal).guard;
    const raw = planned.refusal;
    let sentence = raw;
    // BOOLEANS-GUARD (G9): a refused plan of a combine is turned into one student sentence; (round 5) so is the dependency glue of ANY kind; (G12) a step that needs ONE piece, handed the pieces of an earlier cut
    if ((planned as BoolRefusal).final || isVerbatimGuard(guard)) { /* a sentence of the extrude-pocket group's, or of a guard every set raises (open-outline, move-turn), kept as it is */ }
    else if (f.kind === 'combine') { const p = plainSentence(raw, f as unknown as { op?: string }); sentence = p.sentence; guard ??= p.code; }
    else if (/was refused \(.*\)$/.test(raw)) { const p = plainSentence(raw, f as unknown as { op?: string }); sentence = p.sentence; guard ??= p.code; }
    else { const pp = plainPieces(raw); if (pp) { sentence = pp.sentence; guard ??= pp.code; } }
    st.refused[f.id] = sentence;
    note({ status: 'refused', refusal: sentence, ...(sentence !== raw ? { raw } : {}), ...(guard ? { guard } : {}), commands: [] });
    return;
  }
  if ('noop' in planned) { note({ status: 'noop', commands: [] }); return; }
  const plan = planned as unknown as StepPlan; // named `plan`, as in the original, so that a malformed plan throws the same TypeError text
  let lastErr: string | null = null;
  let timedOut = false;
  let errored = false; // an engine reply with an errored body (errored-body.ts)
  const combine = f.kind === 'combine';
  // time: a combine's engine runs carry { budgetS } (advice to the host, see the header); every other run is as in the original (no option)
  const callSC: RunFn = async (cmds) => {
    const r = await ctx.runSC(cmds, { budgetS: BUDGET_S + 1.5 * bs.lastRunS });
    if (r?.ok && r.cpuMs) bs.lastRunS = r.cpuMs / 1000;
    return r;
  };
  if (plan.r3) { // BOOLEANS-R3: the combine executor decides the command list (it needs the body names each step leaves)
    const ex = await execCombine(plan.r3, accepted, callSC, bs.lastNames ?? []);
    if ('err' in ex) { lastErr = ex.err; timedOut = !!ex.timedOut; errored = !!ex.errored; plan.variants = []; } else { plan.variants = [ex.cmds]; plan.produces = ex.produces; plan.__res = ex.res; }
  }
  let afterGuard: string | undefined;
  let epFinal = false;
  for (const variant0 of plan.variants!) {
    let variant = variant0;
    let repaired: { pads: number; reason: string } | undefined;
    let res: RunResult;
    try { res = plan.__res ?? await ctx.runSC([...accepted, ...variant]); } catch (e) { res = { ok: false, failed: { error: `WASM TRAP: ${(e as Error).message}` } }; }
    if (!res.ok && res.erroredBody) errored = true;
    if (!res.ok) { lastErr = res.failed ? `${res.failed.command}: ${res.failed.error}` : String(res.error ?? 'unknown'); continue; }
    let m = aggregate(res, plan.produces);
    if (!m) { lastErr = `solidcraft ran the commands but no body named ${plan.produces.join(', ')} came back`; continue; }
    // every set: the built pull against its sketch (sketch-volume.ts)
    const sv = f.kind === 'extrude' ? sketchVolumeRefusal(f, st.sketches[f.target], ctx, res, plan.produces) : null;
    if (sv) { st.refused[f.id] = sv; note({ status: 'refused', refusal: sv, guard: SKETCH_VOLUME_GUARD, commands: variant }); return; }
    // every set: a move or turn against the part it started from, a primitive against its closed-form volume (move-turn.ts)
    const mv = motionRefusal(f, st, ctx, res, plan.produces, accepted);
    // the move-turn group's chain repair: the same feature with one or two no-op moves appended, re-checked by the same invariant (move-turn.ts motionRepair)
    const fx = mv ? await motionRepair(f, st, ctx, mv, plan.produces, accepted, variant, ctx.runSC) : null;
    const m2 = fx ? aggregate(fx.res, plan.produces) : null;
    if (mv && fx && m2) { variant = fx.variant; res = fx.res; m = m2; repaired = { pads: fx.pads, reason: mv.sentence }; }
    else if (mv) { st.refused[f.id] = mv.sentence; note({ status: 'refused', refusal: mv.sentence, guard: mv.guard, commands: variant }); return; }
    // a blend of one straight edge between two planar faces adds exactly one face (fillet-chain.ts)
    const bl = blendRefusal(f, blendOf(plan), beforeOf(st, BFV(f).target), m, ctx);
    if (bl) { st.refused[f.id] = bl.sentence; note({ status: 'refused', refusal: bl.sentence, guard: bl.guard, commands: variant }); return; }
    if (combine) { const bad = afterCombine(f as unknown as CombineView, m, plan.before, plan.boxes); if (bad) { lastErr = bad.sentence; afterGuard = bad.code; continue; } } // BOOLEANS-GUARD (G4b, G19, G21): after-check
    if (combine && BFV(f).op === 'union' && epJoinLevel(st, ctx) !== 'off') { // the extrude-pocket group's join checks after the build (unified set only)
      const mE = aggregate(res, plan.produces, true) ?? m;
      let bad: string | null;
      // the extrude-pocket loop lets an engine that throws inside this check reject the whole translation; here it is a failed run of this combine (the same as a throw anywhere else in this step)
      try { bad = await verifyUnion(f, mE, plan.r3!.groups.flat(), { accepted: accepted.slice(), variant, runSC: ctx.runSC, checks: [], scene: st.scene! }, epJoinLevel(st, ctx) === 'full'); } catch (e) { lastErr = `undefined: WASM TRAP: ${(e as Error).message}`; afterGuard = 'EP-JOIN'; continue; }
      if (bad) { lastErr = bad; afterGuard = 'EP-JOIN'; epFinal = true; continue; }
    }
    // the sets with no after-the-build check of a pocket: the cut against the tool that made it (pocket-cut.ts, the extrude-pocket group's check and sentence)
    const pc = f.kind === 'pocket' ? await pocketCutRefusal(f, ctx, res, accepted, variant, plan.produces, ctx.runSC) : null;
    if (pc) { st.refused[f.id] = pc; note({ status: 'refused', refusal: pc, guard: POCKET_CUT_GUARD, commands: variant }); return; }
    // every set: the hollow of a part with rounded or bevelled edges against its closed form (hollow-check.ts)
    const hc = f.kind === 'shell' ? hollowRefusal(f, doc.features, st, ctx, res, plan.produces, accepted) : null;
    if (hc) { st.refused[f.id] = hc.sentence; note({ status: 'refused', refusal: hc.sentence, guard: hc.guard, commands: variant }); return; }
    accepted.push(...variant);
    rememberRun(accepted, res);
    for (const mp of (env.profile.members ?? [env.profile])) mp.onAccepted?.(st, res, m, null, { f, ctx });
    st.accLen[f.id] = accepted.length;
    st.bodies[f.id] = m.bodies;
    st.measure[f.id] = m;
    for (const c of plan.consumes) {
      if (c === f.id) continue;
      if (f.kind === 'hole' || f.kind === 'pocket' || f.kind === 'groove') { if (c === (f.kind === 'hole' ? BFV(f).target : BFV(f).into)) st.head[c] = f.id; } else st.stale[c] = f.id;
    }
    note({ status: 'built', commands: variant, measure: m, pickedFrom: plan.pickedFrom, evidence: plan.evidence ?? null, variantsTried: plan.variants!.indexOf(variant0) + 1, ...(repaired ? { repaired } : {}), pick: (variant.find((c) => c.params.edges || c.params.faces)?.params) ?? null });
    return;
  }
  let sentence: string;
  let code: string | undefined;
  if (errored) { sentence = erroredBodySentence(f); code = ERRORED_BODY_GUARD; } // an errored body (errored-body.ts)
  else if (timedOut && combine) { sentence = SENTENCES.budget(BFV(f).op!); code = 'G-BUDGET'; }
  else if (combine && epFinal) { sentence = lastErr!; code = afterGuard; }
  else if (combine) { const p: GuardHit = plainSentence(lastErr, f as unknown as { op?: string }); sentence = p.sentence; code = afterGuard ?? p.code; } // BOOLEANS-GUARD (G9)
  else sentence = `${f.id} (${f.kind}): solidcraft refused it -- ${lastErr}`;
  st.refused[f.id] = sentence;
  note({ status: 'refused', refusal: sentence, ...(lastErr !== null && lastErr !== sentence ? { raw: lastErr } : {}), ...(code ? { guard: code } : {}), commands: plan.variants![0] ?? [] });
}

export const BOOL_PROFILE: Profile = {
  name: 'booleans',
  // claiming 'combine' is what makes this profile its owner in a composition; the real planning is boolCombine, called by the step through BOOL_PLAN
  planners: { combine: boolCombine },
  verifies: false,
  initState(st, doc) { initBool(st, doc); },
  depSentence: BASE_PROFILE.depSentence,
  noOutline: BASE_PROFILE.noOutline,
  plannerError: BASE_PROFILE.plannerError,
  kernelRefusal: BASE_PROFILE.kernelRefusal,
  // the original's st.lastNames: the bodies the engine held after the last accepted feature, whichever step built it; and how long that run took
  onAccepted(st, res) { st.bool!.lastNames = res.measure!.bodies.map((b) => b.name); if (res.cpuMs) st.bool!.lastRunS = res.cpuMs / 1000; },
  step: boolStep,
};
